def register(add):
    add("T099", title="net/http 客户端：GET 与响应处理", level="intermediate", kind="test-package", runtime="desktop",
        files=["go.mod", "client_test.go"], codeFile="client_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["http.Client", "GET", "httptest", "响应体"],
        summary="用 http.Client 发起 GET 并在本地 httptest 服务器上验证状态码与响应体。",
        objective="能用 http.Client 发起请求、读取响应体，并用 httptest 离线测试。",
        prereq=["T085 io.Reader / io.Writer 抽象"],
        pitfalls=["不关闭 resp.Body：连接无法复用、资源泄漏。", "对真实网络做测试：不稳定且依赖外网；应使 httptest 本地服务器。"],
        exercises=[{"prompt": "断言服务器收到的请求方法，并对非 200 状态做错误处理。", "hint": "在 handler 里检查 r.Method；客户端检查 resp.StatusCode。", "answer": "handler 用 t.Errorf 校验方法；客户端 if resp.StatusCode != 200 { ... }。"}],
        explain="net/http 的客户端核心是 http.Client 与 http.Get/Do。响应体 resp.Body 是 io.ReadCloser，读完必须 Close 以便连接复用。示例用 net/http/httptest.NewServer 起一个本地服务器，完全离线；测试断言状态码 200 与响应体内容。这是 test-package 工程例子（go.mod + *_test.go），用 go test 运行；移动端 net 能力未实测，标 Yaegi*（待实测），默认 desktop。用 httptest 而非真实服务，满足“离线、确定”的硬约束。")
    add("T100", title="net/http 服务端：Handler 与路由", level="intermediate", kind="test-package", runtime="desktop",
        files=["go.mod", "server_test.go"], codeFile="server_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["http.ServeMux", "HandlerFunc", "httptest", "路由"],
        summary="用 http.ServeMux 注册路由，并用 httptest.NewRecorder 直接测试 Handler。",
        objective="能用 ServeMux 注册路由并用 httptest 检查响应，无需真正监听端口。",
        prereq=["T099 net/http 客户端：GET 与响应处理"],
        pitfalls=["把 Mux 直接写在 main 里：难以测试；应抽成 NewMux() 返回路由便于复用。", "在 Handler 里 panic 不处理：会中断服务，需恢复中间件兜底（见 T103）。"],
        exercises=[{"prompt": "新增 /echo 路由回显查询参数 name。", "hint": "r.URL.Query().Get(\"name\")。", "answer": "mux.HandleFunc(\"/echo\", func(w,r){ io.WriteString(w, r.URL.Query().Get(\"name\")) })。"}],
        explain="http.ServeMux 把路径前缀映射到 Handler。http.HandlerFunc 让普通函数满足 Handler 接口。示例把路由抽成 NewMux() 返回 *ServeMux，测试时用 httptest.NewRequest 构造请求、httptest.NewRecorder 捕获响应，直接调用 mux.ServeHTTP——完全离线、不占端口、结果确定。断言路径 /hello 与 /bye 的状态码与响应体。test-package 工程例子，go test 运行，desktop only（移动端 net 未实测）。")
    add("T101", title="请求与响应：Method、Header、状态码", level="intermediate", kind="test-package", runtime="desktop",
        files=["go.mod", "method_test.go"], codeFile="method_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["Method", "Header", "状态码", "405"],
        summary="按方法分支处理请求、读写自定义头，并正确返回 405/201 状态码。",
        objective="能按 r.Method 分支处理、用 w.Header 设置响应头、返回恰当状态码。",
        prereq=["T100 net/http 服务端：Handler 与路由"],
        pitfalls=["用了 w.Write 之后再调 WriteHeader：状态码无效，Go 会警告并忽略。", "405 不带 Allow 头：不符合 HTTP 规范，客户端无法得知允许的方法。"],
        exercises=[{"prompt": "新增一个只接受 PUT 的 /update 路由，返回 204 No Content。", "hint": "方法不符返回 405 并设 Allow: PUT。", "answer": "if r.Method != http.MethodPut { w.Header().Set(\"Allow\", \"PUT\"); w.WriteHeader(405); return }; w.WriteHeader(204)。"}],
        explain="Handler 可以读取请求的 Method 与 Header 并据此分支。写响应时状态码要在写 body 前用 WriteHeader 设定（一旦写入 body 就不能再改状态码）。示例的 handler 只接受 POST，否则返回 405 Method Not Allowed 并设置 Allow 头告知允许方法；成功时回显 X-Token 到 X-Echo 并返回 201。测试分别覆盖 POST 成功与 GET 被拒两条路径，断言状态码与响应头，确定性验证。test-package，go test 运行，desktop only。")
    add("T102", title="JSON API 与错误响应约定", level="intermediate", kind="test-package", runtime="desktop",
        files=["go.mod", "api_test.go"], codeFile="api_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["JSON API", "统一响应", "错误约定", "Content-Type"],
        summary="用统一 envelope 返回成功/错误 JSON，并测试正常与错误两条路径。",
        objective="能设计统一 JSON 响应结构并设置 Content-Type，区分成功与错误响应。",
        prereq=["T089 JSON 一：Marshal/Unmarshal 基础", "T101 请求与响应：Method、Header、状态码"],
        pitfalls=["忘记设置 Content-Type: application/json：客户端可能按文本解析。", "错误响应里也带 data 字段：会混淆调用方，应按约定省略。"],
        exercises=[{"prompt": "为 API 增加分页字段并更新错误约定（如 code 字段）。", "hint": "扩展 Envelope 增加 code；测试断言错误路径含 code 而无 data。", "answer": "Envelope{OK,Data,Error,Code}；错误路径只填 OK/Error/Code。"}],
        explain="一个稳定的 JSON API 应统一响应外壳：成功返回 data，失败返回 error，并始终设置 Content-Type: application/json。示例的 Envelope 用 omitempty 让 data 与 error 互斥出现。测试覆盖两条路径：带 name 参数返回 200 且 data 正确；不带 name 返回 400 且只有 error、无 data。这种“同结构成功/失败”便于客户端统一解析。用 httptest 保证离线与确定。test-package，go test 运行，desktop only。")
    add("T103", title="中间件：日志、恢复与链式组合", level="advanced", kind="test-package", runtime="desktop",
        files=["go.mod", "mw_test.go"], codeFile="mw_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["中间件", "Handler 装饰", "recover", "链式组合"],
        summary="用中间件包裹 Handler 实现日志与 panic 恢复，并按顺序组合成链。",
        objective="能编写 Middleware 函数并组合成链，用 recover 中间件防止 panic 中断服务。",
        prereq=["T100 net/http 服务端：Handler 与路由", "T054 panic 与 recover：边界与代价"],
        pitfalls=["中间件顺序搞反：先执行的应是最外层；chain(h,a,b) 中 a 最先。", "recover 中间件不设状态码：panic 后若不写 header，可能返回 200。"],
        exercises=[{"prompt": "新增一个鉴权中间件，未带 X-Token 时返回 401。", "hint": "在中间件里检查 r.Header.Get(\"X-Token\")。", "answer": "若为空则 w.WriteHeader(401) 并 return，否则 next.ServeHTTP。"}],
        explain="中间件是“接收 Handler、返回 Handler”的函数，可在调用前后插入逻辑（日志、恢复、鉴权）。chain 按顺序包裹：chain(h, a, b) 等价于 a(b(h))，因此 a 是最外层、最先执行。示例用日志中间件记录方法+路径、用 recover 中间件捕获 panic 并返回 500，然后断言：正常请求体正确、panic 请求状态码为 500、日志恰好两条且顺序确定。这展示了中间件链的可组合性与可测试性。test-package，go test 运行，desktop only。")
    add("T104", title="超时、重试与优雅关闭", level="advanced", kind="test-package", runtime="desktop",
        files=["go.mod", "timeout_test.go"], codeFile="timeout_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["超时", "优雅关闭", "Shutdown", "确定性断言"],
        summary="给客户端设超时、给服务器做优雅关闭，并只断言“是否超时/是否关闭成功”。",
        objective="能为 http.Client 设置超时、用 Server.Shutdown 优雅停机，并避免用耗时作断言。",
        prereq=["T099 net/http 客户端：GET 与响应处理", "T083 context 二：超时与截止时间"],
        pitfalls=["不设超时：慢服务会耗尽连接，客户端可能永久阻塞。", "用“耗时约 X 毫秒”作断言：不稳定；应断言是否发生超时。"],
        exercises=[{"prompt": "为客户端加指数退避重试（仅对可重试错误），并测试重试次数。", "hint": "循环调用，失败则 sleep 递增，统计尝试次数。", "answer": "for attempt := 0; attempt < max; attempt++ { ...; if err==nil { break }; time.Sleep(backoff) }。"}],
        explain="生产环境的 HTTP 需要超时与优雅关闭。示例用 httptest 起一个“慢于客户端超时”的服务器，客户端 Client.Timeout 很短，断言必然返回超时错误——只判断“是否超时”，不比较精确耗时。再用 Server.Shutdown(ctx) 做优雅关闭，等待在途请求结束后释放监听，断言关闭调用无错误。这两个主题（超时、关闭）涉及监听，移动端未实测，标 Go only/desktop；测试用 httptest 保证离线。test-package，go test 运行。")
